def _category(refname: str, kind: str) -> str:
    if kind == "decoder":
        return "decoder"
    r = refname.lower()
    if "reverse" in r:
        return "reverse shell"
    if "bind" in r:
        return "bind shell"
    if "exec" in r:
        return "exec"
    if "adduser" in r:
        return "add user"
    if "read_file" in r or "/cat" in r or r.endswith("cat"):
        return "read file"
    if "shell" in r:
        return "shell"
    if "exit" in r:
        return "exit"
    return "misc"


def _dummy_note(refname: str) -> str:
    r = refname.lower()
    if "reverse" in r:
        return "Dummy LHOST 127.0.0.1 / LPORT 4444 baked in — edit to retarget."
    if "bind" in r:
        return "Dummy LPORT 4444 baked in — edit to change."
    if "exec" in r:
        return "Dummy command baked in — edit to change."
    return ""


def _annotate(refname: str, text: str) -> str:
    """Flag the dummy LHOST/LPORT immediates inline so they're easy to spot."""
    net = ("reverse" in refname) or ("bind" in refname)
    compact = text.replace(" ", "").lower()
    if net and "reverse" in refname and ("100007f" in compact):
        return text + "   // LHOST 127.0.0.1 (dummy)"
    if net and ("5c11" in compact or "115c" in compact):
        return text + "   // LPORT 4444 (dummy)"
    return text


def _asm_roundtrips(arch: str, lines: list[str], data: bytes) -> bool:
    """True if assembling the disassembly reproduces the exact original bytes."""
    try:
        results = assemble_lines(arch, lines, 0x1000)
    except Exception:
        return False
    if not results or not all(r.get("ok") for r in results):
        return False
    try:
        out = b"".join(bytes.fromhex(r["bytes"]) for r in results)
    except Exception:
        return False
    return out == data


def _entry(item: dict) -> dict:
    arch = item["arch"]
    kind = item["kind"]
    refname = item["refname"]
    data = bytes.fromhex(item["hex"])
    detail = disassemble_detail(arch, data, 0x1000)
    texts = [t for _, t in detail]
    hexes = [h for h, _ in detail]

    desc = item.get("desc", "") or ""
    note = _dummy_note(refname)
    if note:
        desc = (desc + "  " + note).strip()

    entry = {
        "id": ("msf-dec-" if kind == "decoder" else "msf-") + refname.replace("/", "-"),
        "name": item.get("name") or refname,
        "arch": arch, "os": item["os"],
        "category": _category(refname, kind), "kind": kind, "source": "Metasploit",
        "description": desc, "address": 0x1000, "size": len(data),
    }

    # Payloads load as editable assembly when the disassembly round-trips to the
    # same bytes; everything else (and all decoder stubs) loads as raw bytes.
    if kind == "payload" and texts and _asm_roundtrips(arch, texts, data):
        asm = "\n".join("  " + _annotate(refname, t) for t in texts)
        entry.update(load="asm", asm=asm, preview=asm)
    else:
        entry.update(load="bytes", bytes_lines=hexes, preview="\n".join(texts))
    return entry


def _build() -> list[dict]:
    out = []
    for item in _DATA:
        try:
            out.append(_entry(item))
        except Exception as e:  # one bad entry shouldn't drop the rest
            log.warning("msf entry %s failed: %s", item.get("refname"), e)
    return out


@functools.lru_cache(maxsize=1)
def entries() -> list[dict]:
    """Vendored Metasploit entries, built once. Empty if the engine is
    unavailable."""
    try:
        return _build()
    except Exception as e:
        log.warning("msf catalog unavailable: %s", e)
        return []
